function advAligned(a,b){let m=new Map(advValid(b));return advValid(a).filter(([d])=>m.has(d)).map(([d,v])=>[d,+v,+m.get(d)])}
function advDiff(s){let a=advValid(s);return {points:a.slice(1).map(([d,v],i)=>[a[i][0]+' → '+d,+v-Number(a[i][1])])}}
function advCorr(a,b){if(a.length<30)return null;let x=advMean(a),y=advMean(b),sx=advSd(a),sy=advSd(b);return sx&&sy?advMean(a.map((v,i)=>(v-x)*(b[i]-y)))/(sx*sy):null}
function drawAdvancedChart(div,chart){
 const ss=advSeries(chart),kind=chart.kind,traces=[];let extra={},note=chart.note||'روند مقدار ثبت‌شده؛ تغییرات به‌تنهایی دلیل علّی نیستند.';
 if(!window.Plotly){div.innerHTML='<div class="chart-empty">کتابخانه نمودار بارگذاری نشد؛ اتصال شبکه را بررسی کنید.</div>';return}
 if(!ss.some(s=>advValid(s).length)){div.innerHTML='<div class="chart-empty">در بازه انتخابی داده معتبر وجود ندارد.</div>';return}
 const line=s=>({type:'scatter',mode:'lines',name:s.name,x:s.points.map(p=>p[0]),y:s.points.map(p=>p[1]),connectgaps:false,line:{width:2.1}});
 const xy=s=>({x:s.points.map(p=>p[0]),y:s.points.map(p=>p[1])});
 if(kind==='box'||kind==='histogram'){
   traces.push(...ss.map(s=>kind==='box'?{type:'box',name:s.name,y:advValid(s).map(p=>+p[1]),boxpoints:'outliers',jitter:.25,pointpos:0}:{type:'histogram',name:s.name,x:advValid(s).map(p=>+p[1]),nbinsx:30,opacity:.72}));
   if(kind==='histogram')extra={barmode:'overlay'};
 }else if(kind==='scatter'){
   let pairs=advAligned(ss[0],ss[1]);traces.push({type:'scatter',mode:'markers',name:'مشاهدات هم‌تاریخ',x:pairs.map(p=>p[1]),y:pairs.map(p=>p[2]),text:pairs.map(p=>p[0]),marker:{size:6,opacity:.58,color:ADVANCED_COLORS[0]}});
   extra={xaxis:{title:ss[0].name},yaxis:{title:ss[1].name}};note='تعداد جفت هم‌تاریخ: '+pairs.length+'؛ پراکندگی مشاهده‌ای است و رابطه علّی را اثبات نمی‌کند.';
 }else if(kind==='heatmap'){
   if(ss.length>1){let dates=[...new Set(ss.flatMap(s=>s.points.map(p=>p[0])))].sort();traces.push({type:'heatmap',x:dates,y:ss.map(s=>s.name),z:ss.map(s=>{let m=new Map(s.points);return dates.map(d=>m.has(d)?Number(m.get(d)):null)}),colorscale:'Teal',hoverongaps:false})}
   else{let a=advValid(ss[0]),norm=a.map(p=>[String(p[0]).replace(/\//g,'-'),Number(p[1])]),months=[...new Set(norm.map(p=>p[0].slice(0,7)))].sort(),m=new Map(norm);traces.push({type:'heatmap',x:Array.from({length:31},(_,i)=>i+1),y:months,z:months.map(mon=>Array.from({length:31},(_,i)=>m.get(mon+'-'+String(i+1).padStart(2,'0'))??null)),colorscale:'Teal',hoverongaps:false,colorbar:{title:chart.unit||'مقدار'}});note='نقشه حرارتی تقویم شمسی؛ خانه خالی به معنی نبود رکورد در منبع است.'}
 }else if(kind==='control'||kind==='forecast'){
   let a=advValid(ss[0]);traces.push(line(ss[0]));
   if(a.length>=30){
     if(kind==='control'){const w=30,x=[],midLine=[],upper=[],lower=[],outX=[],outY=[];for(let i=w;i<a.length;i++){const hist=a.slice(i-w,i).map(p=>+p[1]),m=advMean(hist),sd=advSd(hist),v=+a[i][1],d=a[i][0];x.push(d);midLine.push(m);upper.push(m+3*sd);lower.push(Math.max(0,m-3*sd));if(Math.abs(v-m)>3*sd){outX.push(d);outY.push(v)}}traces.push({type:'scatter',mode:'lines',name:'میانگین متحرک ۳۰ مشاهده',x,y:midLine,line:{dash:'dot',color:'#647b8c'}});traces.push({type:'scatter',mode:'lines',name:'حد بالای متحرک',x,y:upper,line:{dash:'dash',color:'#c45f69'}});traces.push({type:'scatter',mode:'lines',name:'حد پایین متحرک',x,y:lower,line:{dash:'dash',color:'#c45f69'}});traces.push({type:'scatter',mode:'markers',name:'بیرون از محدوده',x:outX,y:outY,marker:{color:'#c45f69',size:8}});note='رصد اکتشافی با میانگین و حدود ±۳ انحراف معیارِ ۳۰ مشاهده پیشین؛ '+outX.length+' نقطه بیرون از محدوده. این نمودار جایگزین کنترل‌چارت فرایندی با تعدیل روند و فصل‌مندی نیست.'}
     else{const train=a.slice(0,-1),pred=advMean(train.slice(-7).map(p=>+p[1])),errors=[];for(let i=Math.max(7,train.length-30);i<train.length;i++)errors.push(Math.abs(+train[i][1]-advMean(train.slice(i-7,i).map(p=>+p[1]))));traces[0]=line({...ss[0],points:train});traces.push({type:'scatter',mode:'lines+markers',name:'پیش‌بینی مبنا',x:[train.at(-1)[0],...Array.from({length:7},(_,i)=>'گام +'+(i+1))],y:[+train.at(-1)[1],...Array(7).fill(pred)],line:{dash:'dash',color:'#c38a4a'}});note='پیش‌بینی مبنا با میانگین ۷ مشاهده قبلی؛ MAE آزمون غلتان '+(errors.length?advMean(errors).toLocaleString('fa-IR',{maximumFractionDigits:2}):'—')+'؛ گام‌های آینده تعداد مشاهده‌اند، نه روز تقویمی.'}
   }else note='حداقل ۳۰ مشاهده معتبر لازم است.';
 }else if(['pareto','treemap','sunburst'].includes(kind)){
   let rows=ss.map(s=>({name:s.name,v:advValid(s).reduce((a,p)=>a+Number(p[1]),0)})).filter(r=>r.v>=5).sort((a,b)=>b.v-a.v),total=rows.reduce((a,r)=>a+r.v,0);
   if(kind==='pareto'){let top=rows.slice(0,12),acc=0;traces.push({type:'bar',x:top.map(r=>r.name),y:top.map(r=>r.v),name:'مجموع گزارش‌شده'});traces.push({type:'scatter',mode:'lines+markers',x:top.map(r=>r.name),y:top.map(r=>100*(acc+=r.v)/Math.max(1,total)),yaxis:'y2',name:'درصد تجمعی'});extra={yaxis2:{overlaying:'y',side:'right',range:[0,100]},xaxis:{tickangle:-25},margin:{b:120,l:65,r:55,t:20}}}
   else{let parents=new Map();for(let r of rows){let p=r.name.split(' / ')[0];parents.set(p,(parents.get(p)||0)+r.v)}let ids=['root',...parents.keys(),...rows.map(r=>'leaf:'+r.name)];traces.push({type:kind,ids,labels:['دلایل تماس',...parents.keys(),...rows.map(r=>r.name.split(' / ').slice(1).join(' / '))],parents:['',...Array(parents.size).fill('root'),...rows.map(r=>r.name.split(' / ')[0])],values:[total,...parents.values(),...rows.map(r=>r.v)],branchvalues:'total',textinfo:'label+percent parent'})}
   note='تجمیع سری‌های منبع در بازه انتخابی؛ دسته‌های با مقدار کمتر از ۵ نمایش داده نشده‌اند.';
 }else if(kind==='correlation'||kind==='network'){
   let ds=ss.map(advDiff),z=ds.map(s=>ds.map(t=>{let p=advAligned(s,t);return advCorr(p.map(x=>x[1]),p.map(x=>x[2]))}));
   if(kind==='correlation')traces.push({type:'heatmap',x:ss.map(s=>s.name),y:ss.map(s=>s.name),z,zmin:-1,zmax:1,colorscale:'RdBu',hoverongaps:false});
   else{let pos=ss.map((_,i)=>[Math.cos(2*Math.PI*i/ss.length),Math.sin(2*Math.PI*i/ss.length)]),edges=0;for(let i=0;i<ss.length;i++)for(let j=i+1;j<ss.length;j++){let r=z[i][j];if(r!==null&&Math.abs(r)>=.5){edges++;traces.push({type:'scatter',mode:'lines',x:[pos[i][0],pos[j][0]],y:[pos[i][1],pos[j][1]],text:['r='+r.toFixed(2),'r='+r.toFixed(2)],hoverinfo:'text',showlegend:false,line:{width:1+4*Math.abs(r),color:r>0?'#087e82':'#c15e70'}})}}traces.push({type:'scatter',mode:'markers+text',x:pos.map(p=>p[0]),y:pos.map(p=>p[1]),text:ss.map(s=>s.name),textposition:'top center',marker:{size:22,color:'#254b6c'},showlegend:false});extra={xaxis:{visible:false,range:[-1.35,1.35]},yaxis:{visible:false,range:[-1.3,1.3]}};note=edges+' یال با |r|≥۰٫۵؛ همبستگی تغییرات در تاریخ‌های مشترک.'}
 }else if(kind==='bar'){traces.push(...ss.map(s=>({type:'bar',name:s.name,...xy(s)})))}
 else{traces.push(...ss.map(line))}
 let layout={height:350,autosize:true,font:{family:'Vazirmatn, Tahoma, Arial',size:11,color:'#48634f'},colorway:ADVANCED_COLORS,paper_bgcolor:'#fff',plot_bgcolor:'#fff',margin:{l:65,r:35,t:28,b:76},legend:{orientation:'h',y:-.28},hovermode:'closest',xaxis:{type:'category',nticks:7,gridcolor:'#eaf0ec',automargin:true},yaxis:{gridcolor:'#eaf0ec',automargin:true,title:chart.unit||''},...extra};
 if(kind==='histogram'){layout.xaxis={title:chart.unit||'مقدار',gridcolor:'#eaf0ec'};layout.yaxis={title:'فراوانی',gridcolor:'#eaf0ec'}}else if(kind==='box'){layout.yaxis={title:chart.unit||'مقدار',gridcolor:'#eaf0ec'}}else if(kind==='heatmap'){delete layout.xaxis;delete layout.yaxis}else if(kind==='correlation'){delete layout.xaxis;delete layout.yaxis}else if(kind==='scatter'){layout.xaxis.title=(ss[0]?.name||'X')+' · '+(chart.unit||'');layout.yaxis.title=(ss[1]?.name||'Y')+' · '+(chart.unit||'')}else if(kind==='treemap'||kind==='sunburst'){delete layout.xaxis;delete layout.yaxis;layout.margin={l:4,r:4,t:8,b:8}}
 Plotly.newPlot(div,traces,layout,{responsive:true,displaylogo:false,modeBarButtonsToRemove:['lasso2d','select2d'],toImageButtonOptions:{format:'png',filename:chart.id}});
 let computed=div.parentElement.querySelector('.computed');if(computed)computed.textContent=note;
}
function drawAdvanced(){
 const root=$('advancedCharts');if(!root)return;
 if(ADVANCED_OBSERVER){ADVANCED_OBSERVER.disconnect();ADVANCED_OBSERVER=null}
 if(window.Plotly)root.querySelectorAll('.plot').forEach(p=>{if(p.data)Plotly.purge(p)});
 if(!ADVANCED_DATA||!Object.keys(ADVANCED_DATA).length){root.innerHTML='<div class="chart-empty">داده نمودارهای پیشرفته در دسترس نیست.</div>';return}
 let group=$('advancedGroup')?.value||'',q=($('advancedSearch')?.value||'').trim().toLowerCase(),items=[];
 for(const [key,charts] of Object.entries(ADVANCED_DATA)){for(const c of charts){if((!group||c.group===group)&&(!q||c.title.toLowerCase().includes(q)||c.source.toLowerCase().includes(q)))items.push({...c,section:key})}}
 $('advancedCount').textContent=items.length+' نمودار منتخب';
 root.innerHTML='';
 if(!items.length){root.innerHTML='<div class="chart-empty">نموداری با این فیلتر پیدا نشد.</div>';return}
 let observer='IntersectionObserver'in window?new IntersectionObserver(entries=>{for(let e of entries)if(e.isIntersecting){observer.unobserve(e.target);drawAdvancedChart(e.target,e.target.chart)}},{rootMargin:'260px'}):null;ADVANCED_OBSERVER=observer;
 for(const c of items){let card=document.createElement('article');card.className='panel';let head=document.createElement('div');head.className='panel-head';let left=document.createElement('div'),h=document.createElement('h3'),sub=document.createElement('p');h.textContent=c.title;sub.textContent=c.source+' · '+c.unit;left.append(h,sub);let tag=document.createElement('span');tag.className='source-tag';tag.textContent=(ADVANCED_LABELS[c.section]||c.section)+' · '+c.kind;head.append(left,tag);let plot=document.createElement('div');plot.className='plot';plot.chart=c;let note=document.createElement('div');note.className='computed';note.textContent=c.note||'تحلیل اکتشافی';card.append(head,plot,note);root.append(card);if(observer)observer.observe(plot);else drawAdvancedChart(plot,c)}
}

function drawCatalog(){let inv=DATA.inventory;renderKpis('catalogKpis',`${kpiHtml('فایل‌های CSV',fmt(DATA.meta.csvFiles),'',null,'▤','#087f78','#dff3ef')}${kpiHtml('فایل‌های Excel',fmt(DATA.meta.xlsxFiles),'',null,'▦','#3269b4','#e8f0fc')}${kpiHtml('جداول جاسازی‌شده',fmt(DATA.meta.tableCount),'',null,'▤','#7565b5','#f0edfb')}${kpiHtml('رکوردهای تجمیع‌شده',compact(inv.reduce((a,x)=>a+(x.rows||0),0)),'',null,'∑','#bf7d27','#fff2df')}`);$('catalogCount').textContent=fmt(inv.length)+' منبع/شیت';let secs=[...new Set(inv.map(x=>x.section))].sort();$('catalogSection').innerHTML='<option value="">همه بخش‌ها</option>'+secs.map(s=>`<option>${esc(s)}</option>`).join('');CATALOG_PAGE=1;renderCatalog()}
function renderCatalog(){let q=$('catalogFilter').value.trim().toLowerCase(),sec=$('catalogSection').value;let inv=DATA.inventory.filter(x=>(!sec||x.section===sec)&&(!q||[x.name,x.source,x.section,x.format].join(' ').toLowerCase().includes(q)));let pages=Math.max(1,Math.ceil(inv.length/20));CATALOG_PAGE=Math.min(CATALOG_PAGE,pages);let rows=inv.slice((CATALOG_PAGE-1)*20,CATALOG_PAGE*20);$('catalogTable').innerHTML=formatTable(['منبع / جدول','بخش','قالب','رکورد','از تاریخ','تا تاریخ','اقدام'],rows.map(x=>[x.name,x.section,x.format,fmt(x.rows),fmtDate(x.dateMin),fmtDate(tableObservedCutoff(x.name)||x.dateMax),{html:`<button class="btn" data-open-table="${esc(x.name)}">مشاهده</button>`}]));$('catalogFiltered').textContent=fmt(inv.length)+' منبع';$('catalogPagination').innerHTML=`<span>صفحه ${fmt(CATALOG_PAGE)} از ${fmt(pages)}</span><div><button class="btn" id="catPrev" ${CATALOG_PAGE<=1?'disabled':''}>قبلی</button> <button class="btn" id="catNext" ${CATALOG_PAGE>=pages?'disabled':''}>بعدی</button></div>`;$('catPrev')?.addEventListener('click',()=>{CATALOG_PAGE--;renderCatalog()});$('catNext')?.addEventListener('click',()=>{CATALOG_PAGE++;renderCatalog()});document.querySelectorAll('[data-open-table]').forEach(b=>b.addEventListener('click',()=>openTable(b.dataset.openTable)))}
function openTable(key){selectedTable=key;EXPLORER_PAGE=1;$('exportCurrentTable').disabled=false;$('rowFilter').disabled=false;$('rowFilter').value='';let t=table(key);$('explorerSubtitle').textContent=key+' · '+fmt(t.rows.length)+' رکورد';renderExplorer()}
function renderExplorer(){if(!selectedTable)return;let t=table(selectedTable),q=$('rowFilter').value.trim().toLowerCase();let rows=t.rows.filter(r=>!q||r.some(v=>String(v??'').toLowerCase().includes(q)));let pages=Math.max(1,Math.ceil(rows.length/25));EXPLORER_PAGE=Math.min(EXPLORER_PAGE,pages);let slice=rows.slice((EXPLORER_PAGE-1)*25,EXPLORER_PAGE*25);$('explorerTable').innerHTML=formatTable(t.columns,slice);$('explorerPagination').innerHTML=`<span>${fmt(rows.length)} ردیف مطابق فیلتر · صفحه ${fmt(EXPLORER_PAGE)} از ${fmt(pages)}</span><div><button class="btn" id="expPrev" ${EXPLORER_PAGE<=1?'disabled':''}>قبلی</button> <button class="btn" id="expNext" ${EXPLORER_PAGE>=pages?'disabled':''}>بعدی</button></div>`;$('expPrev')?.addEventListener('click',()=>{EXPLORER_PAGE--;renderExplorer()});$('expNext')?.addEventListener('click',()=>{EXPLORER_PAGE++;renderExplorer()})}
function downloadCSV(key){let t=table(key);if(!t)return;let csv=[t.columns,...t.rows].map(r=>r.map(v=>'"'+String(v??'').replace(/"/g,'""')+'"').join(',')).join('\r\n');let blob=new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8;'});let url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=key.replace(/[^\w\u0600-\u06FF.-]+/g,'_')+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function renderPage(page,force=false){if(!force&&RENDERED_PAGES.has(page))return;const renderers={overview:drawOverview,messenger:drawMessenger,tamasha:drawTamasha,search:drawSearch,traffic:drawTraffic,support:drawSupport,quality:drawQuality,growth:drawGrowth,analytics:drawAdvanced,catalog:drawCatalog};const render=renderers[page];if(render){render();RENDERED_PAGES.add(page)}}
function renderCurrentPage(force=false){const active=document.querySelector('.page.active')?.id?.replace('page-','')||ACTIVE_PAGE;renderPage(active,force)}
function setPage(page){ACTIVE_PAGE=page;document.querySelectorAll('.page').forEach(p=>p.classList.toggle('active',p.id==='page-'+page));document.querySelectorAll('.nav-btn').forEach(b=>b.classList.toggle('active',b.dataset.page===page));$('pageTitle').textContent=PAGE_INFO[page][0];$('pageSubtitle').textContent=PAGE_INFO[page][1];renderPage(page);window.dispatchEvent(new CustomEvent('shad:page-change',{detail:{page}}));window.scrollTo({top:0,behavior:'smooth'})}
function renderAll(){renderPage('overview',true)}
async function loadData(){try{const bytes=new Uint8Array(await (await fetch(DATA_URL)).arrayBuffer());if(!('DecompressionStream'in window))throw new Error('این مرورگر از بازکردن داده فشرده پشتیبانی نمی‌کند.');const stream=new Blob([bytes]).stream().pipeThrough(new DecompressionStream('gzip'));const txt=await new Response(stream).text();DATA=JSON.parse(txt);TABLES=DATA.tables;window.dispatchEvent(new CustomEvent('shad:data-ready',{detail:{points:series('Messenger_statistics/DailyActivity','value_num'),snapshot:DATA.meta?.snapshotJalali||''}}));try{const ab=new Uint8Array(await (await fetch('/advanced.json')).arrayBuffer());ADVANCED_DATA=await (await fetch('/advanced.json')).json()}catch(advancedError){console.warn('Advanced charts could not be loaded',advancedError);ADVANCED_DATA={}}ADVANCED_DATA=rebuildAdvancedFromSource();$('snapshotDate').textContent=fmtDate(DATA.meta.snapshotJalali);$('footerMeta').textContent=`${fmt(DATA.meta.fileCount)} فایل · ${fmt(DATA.meta.tableCount)} جدول · آخرین تاریخ کلی ${fmtDate(DATA.meta.snapshotJalali)}`;renderAll();$('loading').remove()}catch(e){$('loading').innerHTML=`<div class="loading-card"><div class="loading-mark is-error" aria-hidden="true">!</div><div class="loading-brand">شاد <span>|</span> نبض</div><h2>بارگذاری داده انجام نشد</h2><p>${esc(e.message)}</p><p>فایل را با نسخه جدید Chrome یا Edge باز کنید.</p></div>`;console.error(e)}}
document.querySelectorAll('.nav-btn').forEach(b=>b.addEventListener('click',()=>setPage(b.dataset.page)));
document.querySelectorAll('[data-range]').forEach(b=>b.addEventListener('click',()=>{RANGE=b.dataset.range;document.querySelectorAll('[data-range]').forEach(x=>x.classList.toggle('active',x===b));renderCurrentPage(true)}));
$('topSearchFilter').addEventListener('input',()=>{SEARCH_PAGE=1;renderTopSearchTable()});$('exportSearchCsv').addEventListener('click',()=>{let t=table('Messenger_statistics/TopSearches');downloadCSV('Messenger_statistics/TopSearches')});$('queryTrendBtn').addEventListener('click',drawQueryTrend);$('queryTrendInput').addEventListener('keydown',e=>{if(e.key==='Enter')drawQueryTrend()});$('advancedGroup').addEventListener('change',drawAdvanced);$('advancedSearch').addEventListener('input',drawAdvanced);$('catalogFilter').addEventListener('input',()=>{CATALOG_PAGE=1;renderCatalog()});$('catalogSection').addEventListener('change',()=>{CATALOG_PAGE=1;renderCatalog()});$('rowFilter').addEventListener('input',()=>{EXPLORER_PAGE=1;renderExplorer()});$('exportCurrentTable').addEventListener('click',()=>selectedTable&&downloadCSV(selectedTable));
loadData();
